using Microsoft.AspNetCore.Identity;
using System.ComponentModel.DataAnnotations;

namespace Identity.Models
{
    public class AppUser : IdentityUser
    {
        public Country Country { get; set; }
        public int    Age    { get; set; }

        [Required]
        public string Salary { get; set; }
    }

    public enum Country
    {
        USA, UK, France, Germany, Russia
    }
}

[HttpPost]
public async Task<IActionResult> Create(User user)
{
    if (ModelState.IsValid)
    {
        var appUser = new AppUser
        {
            UserName = user.Name,
            Email    = user.Email,
            Country  = user.Country,
            Age      = user.Age,
            Salary   = user.Salary
        };

        IdentityResult result =
            await userManager.CreateAsync(appUser, user.Password);

        if (result.Succeeded)
            return RedirectToAction("Index");

        foreach (IdentityError error in result.Errors)
            ModelState.AddModelError("", error.Description);
    }
    return View(user);
}

[HttpPost]
public async Task<IActionResult> Update(
    string id, string email, string password,
    int age, string country, string salary)
{
    AppUser user = await userManager.FindByIdAsync(id);
    if (user != null)
    {
        if (!string.IsNullOrEmpty(email))
            user.Email = email;
        else
            ModelState.AddModelError("", "Email cannot be empty");

        if (!string.IsNullOrEmpty(password))
            user.PasswordHash =
                passwordHasher.HashPassword(user, password);
        else
            ModelState.AddModelError("", "Password cannot be empty");

        user.Age    = age;
        user.Salary = salary;

        Enum.TryParse(country, out Country myCountry);
        user.Country = myCountry;

        if (!string.IsNullOrEmpty(salary))
        {
            IdentityResult result = await userManager.UpdateAsync(user);
            if (result.Succeeded)
                return RedirectToAction("Index");
            Errors(result);
        }
        else
            ModelState.AddModelError("", "Salary cannot be empty");
    }
    else
        ModelState.AddModelError("", "User Not Found");
    return View(user);
}
